<?php
require_once dirname(__DIR__).'/src/bootstrap.php';
if(Auth::check()) redirect(Auth::dashboardPath(Auth::user()));
$userId=(int)($_SESSION['mfa_pending_user_id']??0);if(!$userId)redirect('login.php');
$stmt=db()->prepare("SELECT * FROM users WHERE id=? AND status='active'");$stmt->execute([$userId]);$u=$stmt->fetch();if(!$u)redirect('login.php');$error=null;
if(request_method('POST')){Csrf::verify();$action=$_POST['action']??'verify';if($action==='resend'){try{$dev=(new MfaService())->begin($u);if($dev!==null)$_SESSION['dev_mfa_otp']=$dev;else unset($_SESSION['dev_mfa_otp']);flash('success','A new MFA code has been prepared.');redirect('mfa.php');}catch(Throwable $e){$error=$e->getMessage();}}else{if((new MfaService())->verify($userId,trim($_POST['otp']??''))){Auth::completeLogin($userId);redirect(Auth::dashboardPath(Auth::user()));}$error='The MFA code is invalid or expired.';}}
$pageTitle='MFA Verification';require dirname(__DIR__).'/src/templates/header.php';?>
<div class="form-card narrow"><div class="eyebrow">Multi-factor authentication</div><h1>Verify your sign-in</h1><p class="help">Enter the 6-digit code sent for this sign-in.</p><?php if((string)config('app','env')==='local'&&!empty($_SESSION['dev_mfa_otp'])):?><div class="flash success"><strong>Local development MFA code:</strong> <?=e((string)$_SESSION['dev_mfa_otp'])?><br><small>Visible only in local development mode.</small></div><?php endif;?><?php if($error):?><div class="error-list"><?=e($error)?></div><?php endif;?><form method="post"><?=Csrf::field()?><input type="hidden" name="action" value="verify"><div class="field"><label>Verification code</label><input name="otp" inputmode="numeric" maxlength="6" pattern="\d{6}" autocomplete="one-time-code" required></div><button class="btn">Verify & Sign In</button></form><form method="post" class="mt-2"><?=Csrf::field()?><input type="hidden" name="action" value="resend"><button class="btn btn-outline">Send a new code</button></form></div>
<?php require dirname(__DIR__).'/src/templates/footer.php';?>
